export const MconnDayOfWeek = {
    SUNDAY: 'Sunday',
    MONDAY: 'Monday',
    TUESDAY: 'Tuesday',
    WEDNESDAY: 'Wednesday',
    THURSDAY: 'Thursday',
    FRIDAY: 'Friday',
    SATURDAY: 'Saturday'
} as const;

export type MconnDayOfWeek = typeof MconnDayOfWeek[keyof typeof MconnDayOfWeek];

export type MconnEmbargoDate = string;

export type MconnEnvelope = {
    errors?: Array<MconnCodedMessage>;
    messages?: Array<MconnCodedMessage>;
    success: boolean;
};

/**
 * Event kind plus event-specific payload fields.
 *
 * Event kinds:
 * - `Init`: Initialized process
 * - `Leave`: Stopped process
 * - `StartAttestation`: Started attestation
 * - `FinishAttestationSuccess`: Finished attestation
 * - `FinishAttestationFailure`: Failed attestation
 * - `StartRotateCryptKey`: Started crypt key rotation
 * - `FinishRotateCryptKeySuccess`: Finished crypt key rotation
 * - `FinishRotateCryptKeyFailure`: Failed crypt key rotation
 * - `StartRotatePki`: Started PKI rotation
 * - `FinishRotatePkiSuccess`: Finished PKI rotation
 * - `FinishRotatePkiFailure`: Failed PKI rotation
 * - `StartUpgrade`: Started upgrade
 * - `FinishUpgradeSuccess`: Finished upgrade
 * - `FinishUpgradeFailure`: Failed upgrade
 * - `Reconcile`: Reconciled
 * - `ConfigureCloudflaredTunnel`: Configured Cloudflared tunnel
 * - `RekeyInstallBoth`: Installed initial inbound and outbound keys
 * - `RekeyStart`: Installed new inbound key, kept old outbound
 * - `RekeyRestart`: Restarted in-progress rekey with newer key material
 * - `RekeyAdvance`: Confirmed traffic on new inbound key, swapped outbound to new
 * - `RekeyComplete`: Deleted old keys
 * - `RekeyReset`: Deleted all keys after receiving an unexpected key
 */
export type MconnEvent = {
    /**
     * Event kind
     */
    k: 'Init' | 'Leave' | 'StartAttestation' | 'FinishAttestationSuccess' | 'FinishAttestationFailure' | 'StartRotateCryptKey' | 'FinishRotateCryptKeySuccess' | 'FinishRotateCryptKeyFailure' | 'StartRotatePki' | 'FinishRotatePkiSuccess' | 'FinishRotatePkiFailure' | 'StartUpgrade' | 'FinishUpgradeSuccess' | 'FinishUpgradeFailure' | 'Reconcile' | 'ConfigureCloudflaredTunnel' | 'RekeyInstallBoth' | 'RekeyStart' | 'RekeyRestart' | 'RekeyAdvance' | 'RekeyComplete' | 'RekeyReset';
    [key: string]: unknown;
};

export type MconnEventMetadata = {
    /**
     * Time the Event was collected (seconds since the Unix epoch)
     */
    a: number;
    /**
     * Kind
     */
    k: string;
    /**
     * Sequence number, used to order events with the same timestamp
     */
    n: number;
    /**
     * Time the Event was recorded (seconds since the Unix epoch)
     */
    t: number;
};

export type MconnGoodResponse = MconnResponse & {
    errors?: Array<MconnCodedMessage>;
};

/**
 * Interrupt action for a connector.
 */
export type MconnInterrupt = {
    reboot?: {
        /**
         * Purge connector state.
         */
        purge?: boolean;
    };
    restart?: {
        /**
         * Purge connector state.
         */
        purge?: boolean;
    };
    shutdown?: {
        /**
         * Purge connector state.
         */
        purge?: boolean;
    };
};

export type MconnNone = {
    [key: string]: unknown;
} | null;

/**
 * Recorded Event
 */
export type MconnRecordedEvent = {
    e: MconnEvent;
    /**
     * Sequence number, used to order events with the same timestamp
     */
    n: number;
    /**
     * Time the Event was recorded (seconds since the Unix epoch)
     */
    t: number;
    /**
     * Version
     */
    v?: string;
};

export type MconnResponse = {
    messages: Array<MconnCodedMessage>;
    success: boolean;
};

