/**
 * Rate limiting analytics for a zone.
 */
export type RlanalyticsRateLimitAnalytics = {
    /**
     * Mapping from rule ID to human-readable description of the rule.
     */
    labels: {
        [key: string]: string;
    };
    /**
     * Start of the queried time period formatted as RFC 3339.
     */
    since: string;
    /**
     * Length (in seconds) of the time segments dividing the entire time period.
     */
    time_delta: 60 | 3600 | 86400 | 2592000;
    /**
     * Time series with analytics data for each time segment.
     */
    timeseries: Array<RlanalyticsRateLimitAnalyticsTimeseriesPoint>;
    /**
     * Exclusive end of the queried time period formatted as RFC 3339.
     */
    until: string;
    /**
     * Numeric ID of the zone.
     */
    zone_id?: number;
};

/**
 * Rate limiting action counts broken down by action type.
 */
export type RlanalyticsRateLimitAnalyticsActionCounters = {
    /**
     * Count of rule actions of any type triggered.
     */
    all?: number;
    /**
     * Count of allow rule actions triggered.
     */
    allow?: number;
    /**
     * Count of ban rule actions triggered.
     */
    ban?: number;
    /**
     * Count of error rule actions triggered.
     */
    error?: number;
    /**
     * Count of simulate rule actions triggered.
     */
    simulate?: number;
};

/**
 * Action counters for a single colo.
 */
export type RlanalyticsRateLimitAnalyticsColoEntry = {
    actions: RlanalyticsRateLimitAnalyticsActionCounters;
};

/**
 * Action totals and per-colo action counts for a particular rule.
 */
export type RlanalyticsRateLimitAnalyticsRuleRollup = {
    actions: RlanalyticsRateLimitAnalyticsActionCounters;
    /**
     * Maps each colo name to its action counters.
     */
    colos: {
        [key: string]: RlanalyticsRateLimitAnalyticsColoEntry;
    };
    /**
     * Number of active versions of the rate limit rule.
     */
    versions: number;
};

/**
 * Analytics data for a single time segment.
 */
export type RlanalyticsRateLimitAnalyticsTimeseriesPoint = {
    /**
     * Contains rule-level analytics for this time segment.
     */
    rules: {
        [key: string]: RlanalyticsRateLimitAnalyticsRuleRollup;
    };
    /**
     * Start of the time segment formatted as RFC 3339.
     */
    since: string;
    /**
     * Exclusive end of the time segment formatted as RFC 3339.
     */
    until: string;
};

