        durableObjectId?: string;
        entrypoint?: string;
        event?: {
            [key: string]: unknown;
        };
        eventType: 'fetch' | 'scheduled' | 'alarm' | 'cron' | 'queue' | 'email' | 'tail' | 'rpc' | 'jsrpc' | 'websocket' | 'workflow' | 'unknown';
