/**
 * A `deleted` tombstone: retires the provisioned namespace for this
 * class and all of its data. The class must be absent from the
 * uploaded code and no other Worker in the account may bind to the
 * namespace, otherwise the deploy is rejected. No other fields are
 * allowed. Deletion is irreversible.
 *
 */
export type WorkersDurableObjectDeletedExport = {
    /**
     * Tombstone that deletes the namespace.
     */
    state: 'deleted';
    /**
     * Marks this entry as a Durable Object export.
     */
    type: 'durable-object';
};

/**
 * The target side of a two-phase transfer (`state:
 * expecting-transfer`). Declares that this script expects to receive
 * a namespace for this class from the `transfer_from` script. This
 * is a live entry, not a tombstone: bindings resolve through the
 * source's namespace until the source commits with a `transferred`
 * tombstone. `storage` and `transfer_from` are required; `renamed_to`
 * and `transferred_to` are not allowed.
 *
 */
export type WorkersDurableObjectExpectingTransferExport = {
    /**
     * Name of the container (declared in the upload's
     * `metadata.containers`) that backs this Durable Object once the
     * transfer settles. Valid only on live entries.
     *
     */
    container?: string;
    /**
     * Target side of a two-phase transfer.
     */
    state: 'expecting-transfer';
    storage: WorkersExportStorage;
    /**
     * The source script name to receive the namespace from. Must be
     * in the same account and dispatch-namespace context. Present on
     * reads for `expecting-transfer` entries.
     *
     */
    transfer_from: string;
    /**
     * Marks this entry as a Durable Object export.
     */
    type: 'durable-object';
};

/**
 * A live Durable Object export (`state: created`, the default). The
 * platform auto-provisions the namespace on first deploy, matches it
 * on subsequent deploys, and never mutates or deletes it as a side
 * effect of a code-only change. `storage` is required; `renamed_to`,
 * `transferred_to` and `transfer_from` are not allowed on a live
 * entry.
 *
 */
export type WorkersDurableObjectExport = {
    /**
     * Name of the container (declared in the upload's
     * `metadata.containers`) that backs this Durable Object. When
     * set, the namespace is container-enabled. Valid only on live
     * entries.
     *
     */
    container?: string;
    /**
     * Live export. May be omitted; defaults to `created`.
     */
    state?: 'created';
    storage: WorkersExportStorage;
    /**
     * Marks this entry as a Durable Object export.
     */
    type: 'durable-object';
};

/**
 * Any Durable Object export entry (`type: durable-object`), across
 * all lifecycle states. The optional `state` field selects the
 * variant (default `created`); the tombstone states (`deleted`,
 * `renamed`, `transferred`) and the live transfer target
 * (`expecting-transfer`) are the alternatives. The server validates
 * the exact per-state field combinations; fields not listed for a
 * variant are rejected.
 *
 */
export type WorkersDurableObjectExportVariants = WorkersDurableObjectExport | WorkersDurableObjectDeletedExport | WorkersDurableObjectRenamedExport | WorkersDurableObjectTransferredExport | WorkersDurableObjectExpectingTransferExport;

/**
 * A `renamed` tombstone: rewrites the provisioned namespace's class
 * name from this map key to `renamed_to`. The source class may stay
 * in code during the rollout window (an info notice is emitted).
 * `storage`, `transferred_to` and `transfer_from` are not allowed.
 *
 */
export type WorkersDurableObjectRenamedExport = {
    /**
     * Tombstone that renames the namespace's class.
     */
    state: 'renamed';
    /**
     * Marks this entry as a Durable Object export.
     */
    type: 'durable-object';
};

/**
 * A `transferred` tombstone (source side of a two-phase transfer):
 * hands ownership of the provisioned namespace to another script in
 * the same account, named by `transferred_to`. The target must have
 * already deployed a matching `expecting-transfer` entry. The source
 * class may stay in code during the rollout window (an info notice
 * is emitted). `storage`, `renamed_to` and `transfer_from` are not
 * allowed.
 *
 */
export type WorkersDurableObjectTransferredExport = {
    /**
     * Tombstone that transfers the namespace to another script.
     */
    state: 'transferred';
    /**
     * Marks this entry as a Durable Object export.
     */
    type: 'durable-object';
};

/**
 * CacheW configuration for a single `type: worker` entrypoint.
 * When present it overrides the Worker's global
 * `cache_options.enabled` for that entrypoint, so a Worker can turn
 * caching on globally and opt one entrypoint out, or the reverse.
 *
 */
export type WorkersEntrypointCacheOptions = {
    /**
     * Whether caching is enabled for this entrypoint.
     */
    enabled: boolean;
};

/**
 * Optional environment if the Worker utilizes one.
 */
export type WorkersEnvironment = string;

/**
 * Hashed script content, can be used in a If-None-Match header when updating.
 */
export type WorkersEtag = string;

/**
 * A single entry in the `exports` map, keyed by export name (a
 * `WorkerEntrypoint` class name, a Durable Object class name, or
 * `default` for the Worker's default export). The `type`
 * discriminator selects the top-level shape: `worker` entrypoint
 * entries may carry `cache` configuration, while `durable-object`
 * entries are further refined by the optional `state` field
 * (default `created`). Tombstone states (`deleted`, `renamed`,
 * `transferred`) express destructive lifecycle operations
 * declaratively; `expecting-transfer` is the live target side of a
 * transfer. The server validates the exact per-(type, state) field
 * combinations; fields not listed for a variant are rejected.
 *
 */
export type WorkersExportConfig = WorkersWorkerExport | WorkersDurableObjectExportVariants;

/**
 * Durable Object storage backend. `sqlite` is the recommended (and
 * only) backend for new namespaces. `legacy-kv` is accepted only for
 * a class whose namespace already exists as KV-backed; the `exports`
 * flow never provisions a new `legacy-kv` namespace.
 *
 */
export const WorkersExportStorage = { SQLITE: 'sqlite', LEGACY_KV: 'legacy-kv' } as const;

/**
 * Durable Object storage backend. `sqlite` is the recommended (and
 * only) backend for new namespaces. `legacy-kv` is accepted only for
 * a class whose namespace already exists as KV-backed; the `exports`
 * flow never provisions a new `legacy-kv` namespace.
 *
 */
export type WorkersExportStorage = typeof WorkersExportStorage[keyof typeof WorkersExportStorage];

/**
 * Declarative exports for the Worker, keyed by export name. Worker
 * entrypoint entries (`type: worker`) carry cache configuration for
 * that entrypoint. Durable Object entries (`type: durable-object`)
 * are also configured here and drive namespace reconciliation. At
 * most 100 entries; class names are at most 128 characters.
 *
 */
export type WorkersExportsConfigMap = {
    [key: string]: WorkersExportConfig;
};

/**
 * A single blocking reconciliation error. Returned in the v4 error
 * envelope under `meta.details` on the exports reconciliation
 * failure error (code 100402). All per-class failures are reported
 * together, sorted by class name.
 *
 */
export type WorkersExportsReconciliationError = {
    /**
     * The class name the error is about.
     */
    class: string;
    /**
     * Human-readable explanation.
     */
    message: string;
    /**
     * The provisioned namespace the error relates to, when applicable.
     */
    namespace_id?: string;
    /**
     * Other Workers in the account whose bindings block the
     * operation (e.g. a `deleted` tombstone blocked by external
     * bindings).
     *
     */
    referencing_scripts?: Array<string>;
    scenario: WorkersExportsReconciliationScenario;
    /**
     * An actionable hint for resolving the error, when available.
     */
    suggestion?: string;
};

/**
 * The v4 error envelope returned with HTTP 400 when one or more
 * declared `exports` entries fail reconciliation (error code
 * 100402). The top-level error `message` aggregates the per-class
 * failures as human-readable prose; the structured per-class payload
 * is carried in `errors[].meta.details`, sorted by class name.
 *
 */
export type WorkersExportsReconciliationErrorResponse = {
    errors: Array<{
        code: 100402;
        /**
         * Aggregate, multi-line, human-readable summary of every
         * per-class reconciliation failure.
         *
         */
        message: string;
        meta: {
            /**
             * Structured per-class reconciliation failures, sorted
             * by class name.
             *
             */
            details: Array<WorkersExportsReconciliationError>;
        };
    }>;
    messages: Array<unknown>;
    result: null;
    success: false;
};

/**
 * A non-blocking reconciliation info entry. Emitted for stale
 * tombstones (a no-op on this deploy) and for tombstones applied
 * with the source class still in code (the supported zero-downtime
 * rollout pattern).
 *
 */
export type WorkersExportsReconciliationInfo = {
    /**
     * The class name the info entry is about.
     */
    class: string;
    /**
     * Human-readable explanation.
     */
    message: string;
    /**
     * The provisioned namespace the entry relates to, when applicable.
     */
    namespace_id?: string;
    /**
     * Other Workers in the account that still bind to the affected
     * class. Advisory: while non-empty the tombstone is not yet safe
     * to remove — redeploy these Workers with bindings re-pointed
     * first.
     *
     */
    referencing_scripts?: Array<string>;
    scenario: WorkersExportsReconciliationScenario;
};

/**
 * A single applied `renamed` tombstone.
 */
export type WorkersExportsReconciliationRename = {
    /**
     * The original (source) class name.
     */
    from: string;
    /**
     * The new class name (`renamed_to`).
     */
    to: string;
};

/**
 * Summary of what the declarative exports reconciliation did on this
 * upload. Present only on uploads that included an `exports` block.
 * Reconciliation acts on Durable Object entries; `type: worker`
 * entries in the same map do not participate. Every array is always
 * present (possibly empty) so clients can iterate unconditionally.
 * Clients should surface `warnings` prominently, render `info` at
 * lower visibility, and use `removable_entries` as the "safe to
 * delete from your config" hint.
 *
 */
export type WorkersExportsReconciliationResult = {
    /**
     * Class names for which a new namespace was provisioned.
     */
    created: Array<string>;
    /**
     * Class names whose namespace was deleted by a `deleted` tombstone.
     */
    deleted: Array<string>;
    /**
     * Non-blocking info entries (stale tombstones, tombstone applied
     * with class still in code). See `exports_reconciliation_info`.
     *
     */
    info: Array<WorkersExportsReconciliationInfo>;
    /**
     * Source class names whose tombstone entry is now stale and safe
     * to delete from `exports` (no remaining referencing scripts).
     *
     */
    removable_entries: Array<string>;
    /**
     * Applied `renamed` tombstones.
     */
    renamed: Array<WorkersExportsReconciliationRename>;
    /**
     * Phase-1 transfer hints recorded on the target side.
     */
    transfer_pending: Array<WorkersExportsReconciliationTransferPending>;
    /**
     * Committed `transferred` tombstones (phase-2).
     */
    transferred: Array<WorkersExportsReconciliationTransfer>;
    /**
     * Class names whose provisioned namespace was mutated in place.
     */
    updated: Array<string>;
    /**
     * Non-blocking warnings. See `exports_reconciliation_warning`.
     */
    warnings: Array<WorkersExportsReconciliationWarning>;
};

/**
 * Stable, machine-readable tag identifying which reconciliation
 * scenario produced an error, warning, or info entry. Clients may
 * branch on this value instead of parsing `message`.
 *
 */
export const WorkersExportsReconciliationScenario = {
    CODE_CLASS_NOT_IN_EXPORTS: 'code_class_not_in_exports',
    PROVISIONED_CLASS_MISSING_FROM_CONFIG: 'provisioned_class_missing_from_config',
    CONFIG_EXPORT_NOT_IN_CODE: 'config_export_not_in_code',
    CONFIG_REFERENCES_NONEXISTENT_CLASS: 'config_references_nonexistent_class',
    ORPHANED_PROVISIONED_NAMESPACE: 'orphaned_provisioned_namespace',
    STORAGE_TYPE_MISMATCH: 'storage_type_mismatch',
    FREE_TIER_REQUIRES_SQLITE: 'free_tier_requires_sqlite',
    INVALID_EXPORT: 'invalid_export',
    TOMBSTONE_DELETE_CLASS_STILL_IN_CODE: 'tombstone_delete_class_still_in_code',
    TOMBSTONE_DELETE_BLOCKED_BY_EXTERNAL_BINDINGS: 'tombstone_delete_blocked_by_external_bindings',
    TOMBSTONE_RENAMED_TO_OCCUPIED: 'tombstone_renamed_to_occupied',
    TRANSFERRED_PENDING_NOT_FOUND: 'transferred_pending_not_found',
    TRANSFERRED_TARGET_MISSING: 'transferred_target_missing',
    TRANSFERRED_TARGET_MISMATCH: 'transferred_target_mismatch',
    PHASE_ONE_TRANSFER_SOURCE_MISSING: 'phase_one_transfer_source_missing',
    PHASE_ONE_TRANSFER_SOURCE_NAMESPACE_MISSING: 'phase_one_transfer_source_namespace_missing',
    PHASE_ONE_TRANSFER_TARGET_CLASS_PROVISIONED: 'phase_one_transfer_target_class_provisioned',
    PHASE_ONE_TRANSFER_AFTER_COMMIT_MISMATCH: 'phase_one_transfer_after_commit_mismatch',
    PHASE_ONE_TRANSFER_DUPLICATE: 'phase_one_transfer_duplicate',
    PHASE_ONE_TRANSFER_TARGET_IN_DISPATCH_NAMESPACE: 'phase_one_transfer_target_in_dispatch_namespace',
    PHASE_ONE_TRANSFER_SOURCE_IN_DISPATCH_NAMESPACE: 'phase_one_transfer_source_in_dispatch_namespace',
    TRANSFERRED_SOURCE_IN_DISPATCH_NAMESPACE: 'transferred_source_in_dispatch_namespace',
    TRANSFERRED_TARGET_IN_DISPATCH_NAMESPACE: 'transferred_target_in_dispatch_namespace',
    CONTAINER_UNDECLARED_REFERENCE: 'container_undeclared_reference',
    CONTAINER_CLASS_NOT_DURABLE_OBJECT: 'container_class_not_durable_object',
    CONTAINER_WIRING_INCONSISTENT: 'container_wiring_inconsistent',
    CONTAINER_MULTIPLE_DURABLE_OBJECTS: 'container_multiple_durable_objects',
    TRANSFER_CONTAINER_PARITY_MISMATCH: 'transfer_container_parity_mismatch',
    TRANSFER_CONTAINER_PARITY_MISMATCH_ON_COMMIT: 'transfer_container_parity_mismatch_on_commit',
    TOMBSTONE_CLASS_STILL_IN_CODE: 'tombstone_class_still_in_code',
    STALE_TOMBSTONE: 'stale_tombstone',
    TRANSFER_RECEIVE_ALREADY_APPLIED: 'transfer_receive_already_applied',
    TRANSFER_RECEIVE_CLEANUP_COMPLETE: 'transfer_receive_cleanup_complete'
} as const;

/**
 * Stable, machine-readable tag identifying which reconciliation
 * scenario produced an error, warning, or info entry. Clients may
 * branch on this value instead of parsing `message`.
 *
 */
export type WorkersExportsReconciliationScenario = typeof WorkersExportsReconciliationScenario[keyof typeof WorkersExportsReconciliationScenario];

/**
 * A single committed `transferred` tombstone (phase-2 commit).
 */
export type WorkersExportsReconciliationTransfer = {
    /**
     * The source class name that was transferred.
     */
    class: string;
    /**
     * The transfer phase. Currently always `committed`.
     */
    phase: 'committed';
    /**
     * The destination script that now owns the namespace.
     */
    to: string;
};

/**
 * A single phase-1 transfer hint recorded on the target side (a live
 * `expecting-transfer` entry).
 *
 */
export type WorkersExportsReconciliationTransferPending = {
    /**
     * The target-side class name awaiting transfer.
     */
    class: string;
    /**
     * The source script the namespace will be transferred from.
     */
    from: string;
};

/**
 * A non-blocking reconciliation warning. Reserved: no scenario
 * populates this array today (`code_class_not_in_exports` is
 * surfaced as info and `provisioned_class_missing_from_config` is a
 * hard error). Clients should still surface any entries that appear.
 *
 */
export type WorkersExportsReconciliationWarning = {
    /**
     * The class name the warning is about.
     */
    class: string;
    /**
     * Human-readable explanation of the warning.
     */
    message: string;
    /**
     * The provisioned namespace the warning relates to, when applicable.
     */
    namespace_id?: string;
    scenario: WorkersExportsReconciliationScenario;
};

