export type PostItemSearchData = {
    body?: {
        cursor?: string;
        /**
         * Recursive filter supporting AND/OR nesting of conditions. Can be either a leaf condition (field/op/value) or a logical group (and/or array of nested filters).
         */
        filter?: {
            /**
             * Column name to filter on
             */
            field: string;
            /**
             * Comparison operator
             */
            op: 'eq' | 'neq' | 'gt' | 'lt' | 'gte' | 'lte' | 'contains' | 'is_empty' | 'is_not_empty';
            /**
             * Value to compare against (not needed for is_empty/is_not_empty)
             */
            value?: unknown;
        } | {
            /**
             * All conditions must match (AND logic). Each item can recursively contain more filters.
             */
            and: Array<{
                [key: string]: unknown;
            }>;
        } | {
            /**
             * At least one condition must match (OR logic). Each item can recursively contain more filters.
             */
            or: Array<{
                [key: string]: unknown;
            }>;
        };
        limit?: number;
        /**
         * Case-insensitive substring search across all columns. Matches any column containing the term. No relevance ranking.
         */
        q?: string;
        sort?: {
            /**
             * Column name to sort by
             */
            field: string;
            order?: 'asc' | 'desc';
        };
    };
    path: {
        /**
         * Account ID
         */
        account_id: string;
        /**
         * Collection UUID
         */
        collection_id: string;
    };
    query?: never;
    url: '/accounts/{account_id}/cloudforce-one/v2/collections/{collection_id}/search';
};

